x-graphlake-sync-environment: &graphlake-sync-environment
  GOMEMLIMIT: ${GRAPHLAKE_SYNC_GOMEMLIMIT:-2GiB}
  GOGC: ${GRAPHLAKE_SYNC_GOGC:-20}
  GL_SYNC_ARDOQ_DB_URI: ${GL_SYNC_ARDOQ_DB_URI:-postgres://ardoq_graphlake:ardoq_graphlake_pass@postgres:5432/ardoq?sslmode=disable}
  GL_SYNC_ARDOQ_CUSTOMERS_URI: ${GL_SYNC_ARDOQ_CUSTOMERS_URI:-postgres://ardoq_graphlake:ardoq_graphlake_pass@postgres:5432/ardoq_customers?sslmode=disable}
  GL_SYNC_SCHEMAS: ${GL_SYNC_SCHEMAS:-ardoqbundlesproduction}
  GL_SYNC_FULL_SYNC_INTERVAL: ${GL_SYNC_FULL_SYNC_INTERVAL:-0}
  GL_SYNC_HISTORY_BACKFILL: ${GL_SYNC_HISTORY_BACKFILL:-true}
  # Full-state month-end snapshots across the whole history replay, so the
  # replayed store can be queried at a point in time (?snapshot_id=N / ?tag=).
  # `off` replays history without them, which is faster and smaller.
  GL_SYNC_HISTORY_REPLAY_SNAPSHOT_MODE: ${GL_SYNC_HISTORY_REPLAY_SNAPSHOT_MODE:-all}
  GL_SYNC_HISTORY_REPLAY_SNAPSHOT_PART_BYTES: ${GL_SYNC_HISTORY_REPLAY_SNAPSHOT_PART_BYTES:-}
  GL_SYNC_GRAPHLAKE_WRITE_TIMEOUT: ${GL_SYNC_GRAPHLAKE_WRITE_TIMEOUT:-5m}
  GL_SYNC_STREAM_RESET_ON_START: ${GL_SYNC_STREAM_RESET_ON_START:-true}
  GL_SYNC_NATS_URL: ${GL_SYNC_NATS_URL:-nats://nats:4222}
  GL_SYNC_NATS_USER: ${GL_SYNC_NATS_USER:-admin}
  GL_SYNC_NATS_PASSWORD: ${GL_SYNC_NATS_PASSWORD:-password}
  GL_SYNC_JETSTREAM_STREAM: ${GL_SYNC_JETSTREAM_STREAM:-DebeziumStream}
  GL_SYNC_JETSTREAM_SUBJECT: ${GL_SYNC_JETSTREAM_SUBJECT:-cdc.raw.organization.*}
  GL_SYNC_JETSTREAM_CONSUMER: ${GL_SYNC_JETSTREAM_CONSUMER:-graphlake-sync-history-cdc}
  # Local stack only. Nothing here provisions per-organisation GraphLake keypairs,
  # and sync no longer provisions them itself, so reading
  # public.organization.integrations->graphlake would fail every write against a
  # cold cluster that has no registered users. true makes every organisation write
  # as the GraphLake admin identity instead and skips that column entirely.
  # Deployed environments leave this unset: each organisation then writes as
  # itself and cannot reach another organisation's store.
  GL_SYNC_USE_ADMIN_CREDENTIALS_FOR_SYNC: ${GL_SYNC_USE_ADMIN_CREDENTIALS_FOR_SYNC:-true}

