CREATE OR REPLACE PROCEDURE setup_org_schema_cdc_publication(org_label varchar(63), table_name varchar(63))
    LANGUAGE plpgsql AS
$$
DECLARE
    full_table_name text := format('%I.%I', org_label, table_name);
    exists_in_pub   boolean;
BEGIN
    SELECT EXISTS (SELECT 1
                   FROM pg_publication_rel pr
                            JOIN pg_class c ON c.oid = pr.prrelid
                            JOIN pg_namespace n ON n.oid = c.relnamespace
                            JOIN pg_publication p ON p.oid = pr.prpubid
                   WHERE p.pubname = 'cdc_publication'
                     AND n.nspname = org_label
                     AND c.relname = table_name)
    INTO exists_in_pub;

    IF exists_in_pub THEN
        RAISE NOTICE 'Table % already exists in publication cdc_publication.', full_table_name;
    ELSE
        EXECUTE format('SET ROLE %I', org_label);
        EXECUTE format('ALTER PUBLICATION cdc_publication ADD TABLE %I.%I', org_label, table_name);
        RESET ROLE;
        RAISE NOTICE 'Table % added to publication cdc_publication.', full_table_name;
    END IF;
END
$$;
